def dungeon(commands):
    x, y = 0, 0                      # state
    for cmd in commands:             # inputs, one at a time
        if cmd == "N":
            y += 1
        elif cmd == "S":
            y -= 1
        elif cmd == "E":
            x += 1
        elif cmd == "W":
            x -= 1
        # unknown commands: state unchanged
    return [x, y]

